"""Publish native screenshots and receipts. No generated or substituted museum images."""
from pathlib import Path
import json,hashlib,html,re,shutil,zipfile
import markdown
R=Path(__file__).resolve().parents[1]
O=R/'doc/book/iterations/2026-10-09-camera-image-becomes-body'
N=R/'ada_run/encounter_pilot/Shader_05_Patterns'
M=O/'museum';M.mkdir(exist_ok=True)
run=json.loads((N/'report.json').read_text());assert not run['failures'],run['failures']
tests=json.loads((O/'validation/camera-results.json').read_text());assert tests['core']['passed'] and tests['gpu']['passed']
old=json.loads((O/'validation/built-studies.json').read_text());assert all(x['passed'] for x in old['results'])
for p in N.glob('*.png'):shutil.copy2(p,M/p.name)
for n in ['report.json','source_manifest.json','engine.log','stdout.log']:shutil.copy2(N/n,M/n)
names=['Pull the scanlines','Brightness becomes relief','Three colour planes','Fold the image','Curl the view','Shuffle the addresses','A strip stays behind','Rows lose alignment','Let dark pixels go','Wrap the room']
notes=['Sixteen pieces of one picture shift sideways and step into depth. The gaps are between receiver strips.','Image brightness displaces the receiving surface. A white wall becomes a ridge even when it was far from the camera: brightness is not depth.','Red, green and blue occupy three separated, additive planes. Their overlap also includes the wall behind them.','Eight corrugations gather the image into repeated vertical ridges. A coordinate stays attached while its surface moves.','The flat picture bends around a cylindrical arc. Move sideways to see the receiver’s depth.','Twenty-four tiles read a fixed permutation of the original image addresses. Every tile is used once.','Move the camera after SNAP. Alternate bands retain the earlier view while the others update. Here the source is LIVE; the other nine captures use the same saved frame.','Sixteen rows wrap around after different horizontal offsets. The surface remains flat.','Low-brightness samples disappear. You see the museum behind the receiver; its holes do not change the room’s collisions.','The rectangle closes into a torus. Its geometry meets at the seam; the unrelated image edges need not join convincingly.']
hashes=[hashlib.sha256((M/f'mode-{i:02}.png').read_bytes()).hexdigest() for i in range(1,11)]
assert len(set(hashes))==10,'Captures must show ten distinct views'
styles='''*{box-sizing:border-box}body{margin:0;background:#edeae4;color:#1c2836;font:19px/1.6 Georgia,serif}header,main,footer{max-width:1480px;margin:auto;padding:32px}h1{font-size:clamp(38px,5vw,74px);line-height:1.05;max-width:1000px}h2{margin-top:2em}p{max-width:85ch}a{color:#365c71}nav{display:flex;flex-wrap:wrap;gap:22px;font:15px system-ui}img{width:100%;height:auto;display:block}figure{margin:0}figcaption{font:14px/1.5 system-ui;padding:12px 0}.pair,.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.card{background:#fffdf7;padding:16px;margin-top:22px}.card h2{margin:.5em 0;font-size:25px}.card p{font:16px/1.6 system-ui}.badge{background:#dce5df;padding:20px;font:16px/1.6 system-ui}pre{background:#1c2836;color:#f4e9dc;padding:22px;overflow:auto;font:13px/1.55 Consolas}table{width:100%;border-collapse:collapse;font:15px/1.6 system-ui}td,th{padding:12px;text-align:left;border-bottom:1px solid #bac4c8;vertical-align:top}details{margin:24px 0}summary{cursor:pointer}footer{font:14px/1.6 system-ui;border-top:1px solid #adb8be}@media(max-width:800px){.pair,.grid{display:block}header,main,footer{padding:20px}}'''
nav='<nav><a href="index.html">Ten museum views</a><a href="evidence.html">Validation and status</a><a href="source.html">How it works / source</a><a href="camera-glitch-review.zip">Review ZIP</a></nav>'
def page(name,title,body):
 (O/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>{styles}</style></head><body><header><p>ENDLESS MUSEUM · SHADER PATTERNS · 9 OCTOBER 2026</p><h1>{html.escape(title)}</h1>{nav}</header><main>{body}</main><footer>Actual native Godot 4.6 museum captures. Desktop + supplied XRTools poses tested; headset and Quest checks remain open.</footer></body></html>',encoding='utf-8')
def fig(src,caption):return f'<figure><a href="{src}"><img src="{src}" alt="{html.escape(caption)}" loading="lazy"></a><figcaption>{html.escape(caption)}</figcaption></figure>'
cards=''.join(f'<article class="card" id="view-{i+1}"><h2>{i+1:02}. {title}</h2>{fig(f"museum/mode-{i+1:02}.png",notes[i])}</article>' for i,title in enumerate(names))
body='<p>One camera watches the existing museum. Its image acquires ten different bodies. Pick up the pink camera, aim, release; compare the unchanged image on the left with the selected receiver on the right.</p>'
body+='<div class="badge">Built and placed in Shader_05_Patterns. 28 geometry checks + 8 GPU checks + '+str(len(run['checks']))+' museum checks pass. Two deliberate geometry faults are rejected. The four earlier studies pass 164 fresh checks; the wider plan is still incomplete.</div>'
body+=fig('museum/mode-02.png','The camera’s picture becomes a relief in the actual museum. This is image brightness made spatial, not reconstructed depth.')
body+='<nav>'+''.join(f'<a href="#view-{i+1}">{i+1:02} {title}</a>' for i,title in enumerate(names))+'</nav><div class="grid">'+cards+'</div>'
body+='<h2>A bay inside the existing hall</h2><p>The study sits in the right side bay after the first chamber, at source cell (17, 13). The pattern garden remains beside it. The exit stays open. This is one optional apparatus with ten modes, rather than ten competing tutorial subjects.</p><div class="pair">'+fig('before/overhead.png','Before: the existing pattern hall and garden.')+fig('museum/overhead.png','After: the camera station occupies the open side bay; existing works stay in place.')+'</div><div class="pair">'+fig('museum/gallery-raised.png','Raised native camera view of the apparatus and its neighbour.')+fig('museum/controls.png','One nearby slider, six buttons and a grabbable camera.')+'</div>'
body+='<h2>Try it</h2><p>NEXT / PREVIOUS select a treatment. AMOUNT controls its strength. SNAP keeps one image; LIVE / HOLD switches between the current camera and that image. For the time bands, SNAP first, stay LIVE, then move the camera. HOME parks the released camera. RESET selects the first mode at 0.8 and returns to LIVE; it keeps the saved image.</p><p><a href="evidence.html">What is complete, what was tested, what remains.</a></p>'
page('index.html','The room, read ten ways',body)
rows=''.join(f'<tr><td>{x["study"]}</td><td>{x["checks"]} / {x["checks"]}</td><td>Fresh native run; source hashes match the earlier receipt.</td></tr>' for x in old['results'])
evidence=f'''<h2>Have we built all examples?</h2><p>No. G0 geometry noise, G1 the disturbed pendulum, G2 imperfect observation and P1 different time steps are built. This camera study adds ten working image treatments. The remaining original packages still need implementation and evidence.</p><table><tr><th>Built study</th><th>Checks</th><th>Evidence today</th></tr>{rows}<tr><td>Camera study</td><td>28 geometry + 8 GPU + {len(run['checks'])} museum</td><td>Native checks, captures, controls and route. Two actual faulty copies fail.</td></tr></table><p>P2 feedback; P3 sampling budget; P4 saved-data interpretation and decoder comparison; P5 explicit fuzzy rules; P6 deliberate state/fault experiments remain proposed. These camera mappings prepare P4 but do not complete that lesson. The other intervention candidates in the <a href="../../course/uncertainty-plan/noise-tests.html">larger plan</a> are not all built.</p>
<h2>What the tests establish</h2><p>Geometry stays finite and bounded; zero restores the rectangle’s vertices and UVs. The tile permutation is bijective, and the torus closes at both seams. Controlled native shader fixtures establish actual brightness displacement, red/blue saved-frame bands, fragment removal and separate RGB output. Two copied models deliberately repeat every tile or leave a torus seam open; the relevant tests reject both.</p><p>The museum run verifies a real shared World3D, nonempty source pixels, exclusion of display/HUD layers, one bounded viewport, ten receiver selections, saved-image preservation, six desktop pointer controls, an actual XRTools pickup/release and held slider driven by supplied controller poses. A supported capsule route reaches the controls and continues to the exit ({run['observations']['route_samples']} samples). Camera-retention checks are included in the museum total; they are not extra interaction tests.</p>
<h2>Corrections made while validating</h2><p>The first proposed front bay was outside the narrow first chamber. A later position behind the pattern garden had an obstructed sightline; it was moved to the side bay. The first walking path crossed an existing support, and a clear route was tested instead. HOME needed to restore both the camera node and its frozen physics pose in the transformed hall.</p><p>The initial controlled GPU tests inherited the project’s changing environment. Their colour oracle was invalid under that fog and sky. A camera-specific black environment isolates the fixture; the museum itself keeps its normal atmosphere. Failed receipts are retained in the validation folder.</p>
<h2>Limits</h2><p>This is a deliberate display experiment. It does not corrupt the observed room or prove GPU failure. Brightness is not depth. RGB blending includes its background, so zero geometric offset is not a pixel-identical recombination claim. The torus can close geometrically while its texture seam remains visible. These receivers have no collision geometry.</p><p>The current Godot build passes these focused checks, with no new script or shader compilation errors. The project still reports an existing unknown resource UID, a Jolt solver-bias warning and an authored-entry fallback. This work does not certify the whole project, headset comfort, Quest performance, full portal traversal or an independent student’s reconstruction.</p>
<h2>Receipts</h2><ul><li><a href="validation/built-studies.json">Four-study fresh validation</a></li><li><a href="validation/camera-core.json">28 geometry checks</a></li><li><a href="validation/camera-gpu.json">8 controlled shader checks and measured colours</a></li><li><a href="validation/camera-results.json">Core, GPU and deliberately faulty variants</a></li><li><a href="museum/report.json">Native museum checks and observed controls</a></li><li><a href="museum/stdout.log">Native museum engine output</a></li><li><a href="source-manifest.json">Exact source hashes</a></li><li><a href="placement.json">Single map / generated-row change</a></li></ul>'''
page('evidence.html','Built, checked, still open',evidence)
artifact=R/'commons/artifacts/camera_glitch_study';code_dir=O/'source';code_dir.mkdir(exist_ok=True)
source=markdown.markdown((artifact/'README.md').read_text(),extensions=['tables','fenced_code'])
# These Markdown source paths are explanatory; keep the report's actual links local.
source=source.replace('../../../doc/book/iterations/2026-10-09-camera-image-becomes-body/index.html','index.html')
for p in sorted(artifact.iterdir()):
 if p.suffix not in ['.gd','.gdshader','.tscn']:continue
 shutil.copy2(p,code_dir/p.name)
 source+=f'<details><summary>{html.escape(p.name)} — full production source</summary><p><a href="source/{p.name}">Download this file</a></p><pre><code>{html.escape(p.read_text())}</code></pre></details>'
page('source.html','The image and the receiver',source)
files=list(artifact.glob('*'))+[R/'commons/maps/Shader_05_Patterns/map_data.json',R/'commons/artifacts/registry/shaders.json',R/'tools/probes/camera_glitch_test.gd',R/'tools/probes/camera_glitch_gpu.gd',R/'tools/probes/camera_glitch_room.gd',R/'tools/test_camera_glitch.py',R/'commons/artifacts/spine_studies/witness_camera.gd',R/'commons/ui/control_console.gd']
(O/'source-manifest.json').write_text(json.dumps({p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in files if p.is_file()},indent=2),encoding='utf-8')
with zipfile.ZipFile(O/'camera-glitch-review.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in O.rglob('*'):
  if p.is_file() and p.suffix!='.zip':z.write(p,p.relative_to(O))
 z.writestr('READ-ME.txt','Open index.html. These are actual museum captures. Full source excerpts require the existing Ada museum and supplied XRTools/console dependencies to run. Repository-relative plan links need the repository. Validation is focused, not headset certification.\n')
links=0
for p in O.glob('*.html'):
 for ref in re.findall(r'(?:href|src)="([^"]+)"',p.read_text()):
  if ref.startswith(('http:','https:')):continue
  path,_,anchor=ref.partition('#');dest=p.parent/path if path else p
  assert dest.exists(),(p,ref)
  if anchor and dest.suffix=='.html':assert f'id="{anchor}"' in dest.read_text(),ref
  links+=1
with zipfile.ZipFile(O/'camera-glitch-review.zip') as z:assert z.testzip() is None
(O/'publication.json').write_text(json.dumps({'local_links':links,'unique_native_mode_captures':10,'zip_crc_valid':True,'browser_render_checked':False},indent=2),encoding='utf-8')
print(json.dumps({'links':links,'report':str(O/'index.html'),'zip_mb':round((O/'camera-glitch-review.zip').stat().st_size/1e6,2)}))
